import { Button, Group, Stack } from '@mantine/core';
import { isEmail, isNotEmpty, useForm } from '@mantine/form';
import { notifications } from '@mantine/notifications';
import { ROWS, TableRow } from './data';
import { RowsTable } from './RowsTable';

interface TableValues {
  rows: TableRow[];
}

export function EditableTable() {
  const form = useForm<TableValues>({
    initialValues: {
      rows: ROWS,
    },
    validate: {
      rows: {
        name: isNotEmpty('Required'),
        email: isEmail('Invalid email'),
        quantity: (value) => (Number(value) >= 0 ? null : 'Must be positive'),
      },
    },
  });

  const handleSubmit = (values: TableValues) => {
    const changedRows = values.rows.filter((_, index) => form.isDirty(`rows.${index}`)).length;
    notifications.show({
      title: 'Changes saved',
      message: `${changedRows} rows changed`,
    });
  };

  return (
    <form onSubmit={form.onSubmit(handleSubmit)}>
      <Stack>
        <RowsTable form={form} />

        <Group justify="flex-end">
          <Button size="md" variant="default" onClick={form.reset}>
            Reset all
          </Button>

          <Button size="md" type="submit">
            Save changes
          </Button>
        </Group>
      </Stack>
    </form>
  );
}

import { ArrowCounterClockwiseIcon } from '@phosphor-icons/react';
import { ActionIcon, NumberInput, ScrollArea, Table, TextInput } from '@mantine/core';
import { UseFormReturnType } from '@mantine/form';
import { TableRow } from './data';

interface RowsTableProps {
  form: UseFormReturnType<{ rows: TableRow[] }>;
}

export function RowsTable({ form }: RowsTableProps) {
  const rows = form.getValues().rows.map((row, index) => (
    <Table.Tr key={row.id}>
      <Table.Td>{row.id}</Table.Td>
      <Table.Td>
        <TextInput
          variant="unstyled"
          size="md"
          aria-label="Name"
          {...form.getInputProps(`rows.${index}.name`)}
        />
      </Table.Td>
      <Table.Td>
        <TextInput
          variant="unstyled"
          size="md"
          aria-label="Email"
          {...form.getInputProps(`rows.${index}.email`)}
        />
      </Table.Td>
      <Table.Td>
        <NumberInput
          variant="unstyled"
          size="md"
          hideControls
          min={0}
          max={10000}
          w={70}
          aria-label="Quantity"
          {...form.getInputProps(`rows.${index}.quantity`)}
        />
      </Table.Td>
      <Table.Td>
        <ActionIcon
          variant="default"
          size="input-md"
          aria-label="Reset row"
          onClick={() => form.resetField(`rows.${index}`)}
        >
          <ArrowCounterClockwiseIcon size={16} />
        </ActionIcon>
      </Table.Td>
    </Table.Tr>
  ));

  return (
    <ScrollArea h={400} type="auto" offsetScrollbars>
      <Table verticalSpacing={2} stickyHeader>
        <Table.Thead>
          <Table.Tr>
            <Table.Th w={40}>#</Table.Th>
            <Table.Th>Name</Table.Th>
            <Table.Th>Email</Table.Th>
            <Table.Th>Qty</Table.Th>
            <Table.Th w={40} />
          </Table.Tr>
        </Table.Thead>
        <Table.Tbody>{rows}</Table.Tbody>
      </Table>
    </ScrollArea>
  );
}

export interface TableRow {
  id: number;
  name: string;
  email: string;
  quantity: number;
}

const FIRST_NAMES = [
  'Emma',
  'Liam',
  'Olivia',
  'Noah',
  'Ava',
  'Ethan',
  'Mia',
  'Lucas',
  'Zoe',
  'Leo',
];
const LAST_NAMES = ['Smith', 'Jones', 'Brown', 'Taylor', 'Wilson'];

export function generateRows(count: number): TableRow[] {
  return Array.from({ length: count }, (_, index) => {
    const firstName = FIRST_NAMES[index % FIRST_NAMES.length];
    const lastName = LAST_NAMES[Math.floor(index / FIRST_NAMES.length) % LAST_NAMES.length];

    return {
      id: index + 1,
      name: `${firstName} ${lastName}`,
      email: `${firstName}.${lastName}${index + 1}@example.com`.toLowerCase(),
      quantity: (index * 7) % 20,
    };
  });
}

export const ROWS = generateRows(50);
